<template>
  <main class="patient-preview-page">
    <section class="patient-phone" aria-label="Área do paciente">
      <header class="patient-brand"><span>REALMED<small>Meu cuidado</small></span><span class="patient-avatar" aria-hidden="true">{{ initials }}</span></header>
      <div class="patient-app-actions"><button type="button" :disabled="loading" @click="load()">{{ loading ? 'Atualizando…' : 'Atualizar' }}</button><button type="button" @click="saveOnPhone">Salvar no celular</button></div>
      <div v-if="loading" class="patient-empty" role="status">Carregando seu tratamento…</div>
      <div v-else-if="error" class="patient-empty" role="alert"><h1>Não foi possível abrir esta consulta</h1><p>{{ error }}</p><button type="button" @click="load()">Tentar novamente</button></div>
      <template v-else-if="data">
        <section class="patient-welcome"><p>Seu espaço de cuidado</p><h1>Olá, {{ firstName }}.</h1><span>{{ data.patient.name }}</span><small>Tratamento #{{ data.treatment.rootId }} · Guia {{ data.treatment.guideNumber }}</small><label v-if="data.treatments.length > 1" class="patient-treatment-select">Tratamento<select aria-label="Selecionar tratamento" :value="data.treatment.id" @change="selectTreatment"><option v-for="item in data.treatments" :key="item.id" :value="item.id">#{{ item.rootId }} · Guia {{ item.guideNumber }}{{ item.assessmentDate ? ' · ' + shortDate(item.assessmentDate) : '' }}</option></select></label></section>
        <nav class="patient-tabs" role="tablist" aria-label="Meu tratamento"><button v-for="tab in tabs" :id="'patient-tab-' + tab.id" :key="tab.id" type="button" role="tab" :aria-selected="active === tab.id" :aria-controls="'patient-panel-' + tab.id" :tabindex="active === tab.id ? 0 : -1" @click="active = tab.id" @keydown="tabKey($event, tab.id)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path :d="tab.icon" /></svg>{{ tab.label }}</button></nav>
        <div :id="'patient-panel-' + active" role="tabpanel" :aria-labelledby="'patient-tab-' + active" class="patient-content">
          <template v-if="active === 'home'">
            <article class="patient-card patient-progress"><div class="patient-card-heading"><h2>Meu tratamento</h2><span>{{ treatmentState }}</span></div><p v-if="data.treatment.continuation" class="patient-muted">Continuação do tratamento · avaliação inicial preservada</p><div class="patient-session-count"><strong>{{ data.treatment.performed }}</strong><span>sessões realizadas<span v-if="data.treatment.authorized !== null"> de {{ data.treatment.authorized }} autorizadas</span></span></div><div v-if="(data.treatment.authorized ?? 0) > 0" class="patient-progress-track" role="progressbar" :aria-valuenow="Math.min(data.treatment.performed, data.treatment.authorized ?? 0)" :aria-valuemax="data.treatment.authorized ?? 0" aria-valuemin="0" aria-label="Sessões realizadas"><div :style="{ width: progress + '%' }" /></div><p class="patient-muted">{{ data.treatment.requested ?? '—' }} sessões solicitadas · informação registrada no tratamento.</p><dl><div><dt>Fisioterapeuta</dt><dd>{{ data.treatment.physiotherapist || 'Ainda não informado' }}</dd></div><div><dt>Convênio</dt><dd>{{ data.treatment.insurance || 'Ainda não informado' }}</dd></div></dl></article>
            <article class="patient-card patient-next"><p class="patient-eyebrow">PRÓXIMO ATENDIMENTO REGISTRADO</p><template v-if="nextAppointment"><h2>{{ dayLabel(nextAppointment.date) }}<span>{{ nextAppointment.time }}</span></h2><p>{{ nextAppointment.type }} · {{ nextAppointment.schedule }}</p><span class="patient-status"><i :style="{ background: appointmentStatus(nextAppointment.status).color }" />{{ appointmentStatus(nextAppointment.status).label }}</span></template><template v-else><h2>Seus próximos atendimentos</h2><p>Nenhum horário futuro está disponível nesta consulta. Confirme sua programação com a recepção.</p></template><button type="button" class="patient-inline" @click="active = 'agenda'">Consultar minha agenda <span aria-hidden="true">→</span></button></article>
            <button type="button" class="patient-feature" @click="active = 'evaluation'"><span class="patient-feature-icon" aria-hidden="true">✓</span><span><strong>Minha avaliação</strong><small>{{ data.evaluation ? 'Veja sua avaliação e o plano de cuidado' : 'A avaliação estará disponível após a conclusão' }}</small></span><span aria-hidden="true">›</span></button>
            <button type="button" class="patient-feature" @click="active = 'evolution'"><span class="patient-feature-icon" aria-hidden="true">↗</span><span><strong>Minha evolução</strong><small>Acompanhamento e encerramento do tratamento</small></span><span aria-hidden="true">›</span></button>
          </template>
          <template v-else-if="active === 'agenda'">
            <h2 class="patient-section-title">Minha agenda</h2><p class="patient-muted">Horários registrados para você, incluindo outros tratamentos. Horário de Brasília.</p>
            <div class="patient-segment" aria-label="Período da agenda"><button :aria-pressed="agendaPeriod === 'upcoming'" @click="agendaPeriod = 'upcoming'">Próximos</button><button :aria-pressed="agendaPeriod === 'history'" @click="agendaPeriod = 'history'">Anteriores</button></div>
            <p v-if="!data.agenda.linked" class="patient-note">A agenda ainda não está disponível para este cadastro. Consulte a recepção.</p>
            <div v-else-if="!visibleAppointments.length" class="patient-card patient-empty"><h3>{{ agendaPeriod === 'upcoming' ? 'Nenhum horário futuro nesta consulta' : 'Nenhum atendimento anterior nesta consulta' }}</h3><p>Isso não significa que você não tenha atendimentos. Confirme as informações com a recepção.</p></div>
            <article v-for="(item, index) in visibleAppointments" :key="index" class="patient-card patient-appointment"><div class="patient-appointment-date"><strong>{{ item.date.slice(8, 10) }}</strong><span>{{ monthLabel(item.date) }}</span></div><div><h3>{{ item.type }}</h3><p>{{ item.time }} · {{ item.schedule }}</p><span class="patient-status"><i :style="{ background: appointmentStatus(item.status).color }" />{{ appointmentStatus(item.status).label }}</span></div></article>
            <p v-if="data.agenda.coverage" class="patient-footnote">Informações consultadas de {{ shortDate(data.agenda.coverage.from) }} a {{ shortDate(data.agenda.coverage.to) }}. Última atualização: {{ updatedLabel(data.agenda.coverage.updatedAt) }}. A agenda pode ter alterações após essa data.</p><p v-else class="patient-footnote">Ainda não há uma atualização da agenda disponível nesta consulta.</p><p v-if="data.agenda.limited" class="patient-footnote">Mostrando até 20 horários por período.</p>
          </template>
          <template v-else-if="active === 'evaluation'">
            <h2 class="patient-section-title">Minha avaliação</h2>
            <article v-if="!data.evaluation" class="patient-card patient-empty"><span class="patient-empty-symbol" aria-hidden="true">✓</span><h3>Sua avaliação está sendo preparada</h3><p>Assim que estiver concluída, você poderá consultar aqui o registro e o plano do seu tratamento.</p></article>
            <template v-else><article class="patient-card patient-evaluation-heading"><span class="patient-complete">Avaliação concluída</span><h3>{{ dayLabel(data.evaluation.evaluation_date) }}</h3><p>{{ data.evaluation.responsible_name || 'Responsável não informado' }}</p><small>CREFITO {{ data.evaluation.responsible_crefito || 'não informado' }}</small><p v-if="data.treatment.continuation" class="patient-note">Esta é a avaliação inicial preservada para a continuação do seu tratamento.</p></article>
              <article v-for="section in evaluationSections" :key="section.title" class="patient-card patient-evaluation-section"><h3>{{ section.title }}</h3><dl><template v-for="field in section.fields" :key="field[0]"><div v-if="hasValue(data.evaluation[field[0]])"><dt>{{ field[1] }}</dt><dd>{{ display(data.evaluation[field[0]], field[0]) }}</dd></div></template></dl><p v-if="!section.fields.some(field => hasValue(data?.evaluation?.[field[0]]))" class="patient-muted">Não informado na avaliação.</p></article>
              <article v-if="data.evaluation.body_marks?.length" class="patient-card patient-drawing"><h3>Regiões avaliadas</h3><EvaluationDrawing :model-value="data.evaluation.body_marks" disabled /></article>
            </template>
          </template>
          <template v-else>
            <div class="patient-evolution-title"><div><h2 class="patient-section-title">Minha evolução</h2><p class="patient-muted">Registros finalizados no Stenci pelo seu fisioterapeuta.</p></div><button v-if="evolutions.length" type="button" @click="printEvolution">Imprimir / salvar PDF</button></div>
            <article v-if="!evolutions.length" class="patient-card patient-empty"><span class="patient-empty-symbol" aria-hidden="true">↗</span><h3>Nenhuma evolução finalizada disponível</h3><p>Rascunhos e atendimentos ainda não concluídos não são mostrados aqui.</p></article>
            <article v-for="item in evolutions" v-else :key="item.id" class="patient-card patient-evolution"><div class="patient-card-heading"><h3>{{ dayLabel(item.date) }}</h3><span v-if="item.progress">Sessão {{ item.progress.current }}/{{ item.progress.total }}</span></div><pre>{{ item.text }}</pre></article>
            <article class="patient-card"><h3>Relatório de encerramento</h3><p class="patient-muted">O relatório final ainda não está disponível para consulta. A contagem de sessões, por si só, não representa uma alta clínica.</p></article>
          </template>
        </div>
      </template>
    </section>
    <footer class="patient-footer">REALMED · Cuidado que acompanha você.</footer>
  </main>
</template>
<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import axios from 'axios'
import { usePatientApp } from '@/composables/usePatientApp'
const origin = (import.meta.env.VITE_API_URL || 'http://localhost:3005').replace(/\/+$/, '')
const api = axios.create({ baseURL: (/\/api$/i.test(origin) ? origin : origin + '/api') + '/public/patient-portal', timeout: 20000 })
const { saveOnPhone } = usePatientApp()
import { notify } from '@/composables/useNotifications'
import { appointmentStatus } from '@/utils/physioAgenda'
import EvaluationDrawing from '@/components/EvaluationDrawing.vue'
type Appointment = { date: string; time: string; status: string; type: string; schedule: string; upcoming: boolean }
type Evolution = { id:string;date:string;text:string;progress:{current:number;total:number;final:boolean}|null;professional:{name:string;crefito:string;state:string} }
type Preview = { treatments: { id: number; rootId: number; guideNumber: number; assessmentDate: string | null }[]; patient: { name: string }; treatment: { id: number; rootId: number; guideNumber: number; continuation: boolean; insurance: string | null; physiotherapist: string | null; requested: number | null; authorized: number | null; performed: number; status: string }; evaluation: Record<string, any> | null; evolutions:Evolution[]; agenda: { linked: boolean; upcoming: Appointment[]; history: Appointment[]; limited: boolean; coverage: { from: string; to: string; updatedAt: string } | null } }
const route = useRoute(), data = ref<Preview | null>(null), loading = ref(false), error = ref(''), active = ref('home'), agendaPeriod = ref<'upcoming' | 'history'>('upcoming')
let controller: AbortController | undefined, version = 0, selectedTreatment: number | undefined
const tabs = [{ id: 'home', label: 'Início', icon: 'm3 10 9-7 9 7v11h-6v-7H9v7H3V10Z' }, { id: 'agenda', label: 'Agenda', icon: 'M4 5h16v16H4V5Zm4-3v6m8-6v6M4 10h16M8 14h2m4 0h2M8 17h2' }, { id: 'evaluation', label: 'Avaliação', icon: 'M5 3h10l4 4v14H5V3Zm10 0v5h4M8 12h8M8 16h8' }, { id: 'evolution', label: 'Evolução', icon: 'M3 18 9 12l4 3 8-11m-6 0h6v6M3 3v18h18' }]
const firstName = computed(() => data.value?.patient.name.trim().split(/\s+/)[0] || 'paciente')
const initials = computed(() => data.value?.patient.name.split(/\s+/).filter(Boolean).slice(0, 2).map(part => part[0]).join('') || 'R')
const progress = computed(() => data.value?.treatment.authorized ? Math.max(0, Math.min(100, data.value.treatment.performed / data.value.treatment.authorized * 100)) : 0)
const treatmentState = computed(() => ({ WAITING: 'Em preparação', IN_PROGRESS: 'Em acompanhamento', COMPLETED: 'Ciclo concluído', CANCELED: 'Ciclo cancelado' }[data.value?.treatment.status || ''] || 'Em acompanhamento'))
const nextAppointment = computed(() => data.value?.agenda.upcoming.find(item => ['scheduled', 'confirmed', 'waiting', 'rescheduled'].includes(item.status)))
const visibleAppointments = computed(() => data.value?.agenda[agendaPeriod.value] || [])
const evolutions = computed(() => data.value?.evolutions || [])
const shortDate = (value: unknown) => String(value || '').slice(0, 10).split('-').reverse().join('/') || 'Data não informada'
function dayLabel(value: unknown) { const date = new Date(String(value || '').slice(0, 10) + 'T12:00:00Z'); return Number.isFinite(+date) ? new Intl.DateTimeFormat('pt-BR', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' }).format(date) : 'Data não informada' }
function monthLabel(value: string) { return new Intl.DateTimeFormat('pt-BR', { month: 'short', timeZone: 'UTC' }).format(new Date(value + 'T12:00:00Z')).replace('.', '') }
function updatedLabel(value: string) { const date = new Date(value); return Number.isFinite(+date) ? new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short', timeStyle: 'short', timeZone: 'America/Sao_Paulo' }).format(date) : 'Data não informada' }
function hasValue(value: unknown) { return value !== null && value !== undefined && value !== '' && (!Array.isArray(value) || value.length > 0) }
function display(value: any, key: string): string { if (key.endsWith('_date')) return shortDate(value); if (Array.isArray(value)) return value.map(item => typeof item === 'string' ? item : [item.region || item.name, ({ RIGHT: 'Direita', LEFT: 'Esquerda', BILATERAL: 'Bilateral' } as Record<string, string>)[item.laterality] || item.side].filter(Boolean).join(' · ')).join('\n'); return String(value) }
const evaluationSections = [
  { title: 'Motivo da avaliação', fields: [['chief_complaint', 'Queixa principal'], ['medical_diagnosis', 'Diagnóstico / hipótese médica'], ['referral_professional', 'Profissional solicitante'], ['referral_date', 'Encaminhamento']] },
  { title: 'Como você estava na avaliação', fields: [['functional_limitations', 'Limitações relatadas'], ['physical_exam', 'Exame físico'], ['pain_score', 'Dor inicial (0 a 10)'], ['pain_location', 'Localização da dor'], ['regions', 'Regiões avaliadas'], ['other_region', 'Outra região']] },
  { title: 'Seu plano de cuidado', fields: [['therapeutic_goals', 'Objetivos'], ['conducts', 'Condutas'], ['other_conduct', 'Outras condutas'], ['conduct_description', 'Plano e progressão']] },
  { title: 'Orientações e acompanhamento', fields: [['precautions', 'Precauções'], ['other_precaution', 'Outras precauções'], ['specific_care_notes', 'Cuidados específicos'], ['reevaluation_date', 'Reavaliação prevista'], ['reevaluation_notes', 'Acompanhamento']] },
]
function selectTreatment(event: Event) { selectedTreatment = Number((event.target as HTMLSelectElement).value); void load() }
function printEvolution(){window.print()}
async function load() {
  const current = ++version; controller?.abort(); controller = new AbortController(); loading.value = true; error.value = ''; data.value = null
  try { const response = await api.post('/view', { code: String(route.params.code), treatmentId: selectedTreatment }, { signal: controller.signal }); if (current === version) data.value = response.data }
  catch (e: any) { if (e.code !== 'ERR_CANCELED' && current === version) { error.value = e.response?.data?.error || 'Não foi possível carregar os dados do paciente.'; notify(error.value, 'error') } }
  finally { if (current === version) loading.value = false }
}
async function tabKey(event: KeyboardEvent, key: string) { if (!['ArrowRight', 'ArrowLeft', 'Home', 'End'].includes(event.key)) return; event.preventDefault(); const index = tabs.findIndex(tab => tab.id === key); active.value = tabs[event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (index + (event.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length].id; await nextTick(); document.getElementById('patient-tab-' + active.value)?.focus() }
watch(() => route.params.code, () => { selectedTreatment = undefined; active.value = 'home'; void load() }, { immediate: true })
onBeforeUnmount(() => { version++; controller?.abort(); data.value = null })
</script>
<style scoped>
